export function getSegment3pTimingAbortMarkers(segment3pTimings) {
  if (!segment3pTimings) {
    return {};
  }
  const aborts = [];
  for (const [segmentId, entries] of Object.entries(segment3pTimings)) {
    for (const entry of entries) {
      if (entry.label === 'segment-timing-abort') {
        aborts.push({
          segmentId,
          data: entry.data
        });
      }
    }
  }
  return aborts.length > 0 ? {
    segment3pTimingAborts: aborts
  } : {};
}